void write(inout vec4 w, in vec4 data, in vec2 pos, in vec2 fragCoord) {
    if (floor(pos) == floor(fragCoord)) {
        w = data;
    }
}

bool keyDown(int ascii) {
    return texelFetch(iChannel1,ivec2(ascii,0),0).x > 0.;
}

vec3 processPoint(vec3 point, float deltaTime) {
    float speed = .5;
    float t = 10.;
    float p = 50.;
    float b = 4./3.;
    float x = point.x;
    float y = point.y;
    float z = point.z;

    vec3 delta;
    delta.x = t * (y - x);
    delta.y = x * (p - z) - y;
    delta.z = x*y - b*z;
    deltaTime = min(deltaTime, 1./30.);
    return point + delta*deltaTime*speed;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 c = fragCoord;
    vec4 r = read(c);
    vec4 w = r;

    write(w, read(c-prev), c, c);
    if (int(c.x) == 0  && int(c.y) < pCnt) {
        if (r.xyz == vec3(0.) || length(c) > 1000. || keyDown(32)) {
            write(w, vec4(hash23(fragCoord), 1.), c, c);
        }else {
            write(w, vec4(processPoint(r.xyz, iTimeDelta), 1.), c, c);
        }
    }

    fragColor = w;
}

float lineSegment( vec2 a, vec2 b, vec2 p, float w ) {
    vec2 ba = b - a;
    vec2 pa = p - a;

    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    vec2 cp = a + h * ba;

    float d = length(p - cp);

    return clamp(1.-floor(smoothstep(0., w, d)), 0., 1.);
}

vec4 read(vec2 fragCoord) {
    return texelFetch(iChannel0,ivec2(fragCoord), 0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    vec2 tuv = fragCoord/iResolution.xy;
    uv -= iResolution.xy/iResolution.y/2.;
    uv *= 80.;
    vec3 col = vec3(0.);

    for (int i = 0; i < pCnt; i++) {
        vec2 a = vec2(0., float(i));
        vec2 aPrev = vec2(1., float(i));
        vec3 p1 = read(a).xyz;
        vec3 p1prev = read(aPrev).xyz;

        // Time varying pixel color
        float l = lineSegment(p1.yx, p1prev.yx, uv, .1);

        vec3 add = l*hslToRgb(vec3(fract(iTime*0.1), hash23(vec2(float(i), float(i)*384.)).x*.4+.2, p1.z/130. + .1));
        col = mix(col, add, clamp(length(add), 0., 10.));
    }
    vec3 tex = clamp(texture(iChannel1, tuv).rgb * .99, 0., 1.);
    col = mix(tex, col, length(col));
    //col = texture(iChannel0, uv).rgb;
    // Output to screen
    fragColor = vec4(col, 1.);
}

vec2 p = vec2(0.);
vec2 prev = vec2(1., 0.);

int pCnt = 30;

vec3 hash23(vec2 p) {
    vec3 p3 = fract(vec3(p.x, p.y, p.x) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xxy + p3.yzz) * p3.zyx);
}

vec3 hslToRgb(vec3 hsl) {
    float h = hsl.x;
    float s = hsl.y;
    float l = hsl.z;

    float c = (1.0 - abs(2.0 * l - 1.0)) * s;
    float x = c * (1.0 - abs(mod(h * 6.0, 2.0) - 1.0));
    float m = l - c * 0.5;

    vec3 rgb;

    if (h < 1.0 / 6.0) {
        rgb = vec3(c, x, 0.0);
    } else if (h < 2.0 / 6.0) {
        rgb = vec3(x, c, 0.0);
    } else if (h < 3.0 / 6.0) {
        rgb = vec3(0.0, c, x);
    } else if (h < 4.0 / 6.0) {
        rgb = vec3(0.0, x, c);
    } else if (h < 5.0 / 6.0) {
        rgb = vec3(x, 0.0, c);
    } else {
        rgb = vec3(c, 0.0, x);
    }

    return rgb + m;
}
